-- =====================================================================================
-- PIPING 8.63 · Accesorios de polietileno (PE): compresión PP, electrofusión, soldadura a tope, collarines de toma,
-- transiciones PE-rosca, bridas y juntas, roscados y piezas de depósito.
-- Fuentes: EGB (manual técnico PP compresión y tarifa 2022), Cepex (catálogo técnico PP; collarines vía Poolaria),
-- Suinga (La Tienda del Jardín). Generado desde Accesorios_PE.xlsx.
-- Cada modelo tiene sus medidas en piping_acc_cotas (dn = diámetro exterior del tubo PE en mm; dn2 = medida menor,
-- derivación o rosca equivalente en DN). El texto «cotas» lleva Ref, L, Z, rosca, PN, Dint, d paso y los K por medida:
-- K (paso, ref. salida), Kd (derivación) y Ki (sentido inverso). PIPING 8.63 usa esos K en el cálculo.
-- Ejecutar en Supabase > SQL Editor después de 07, 11 y 12. Se puede repetir: actualiza las filas existentes.
-- =====================================================================================
begin;
alter table public.piping_acc_modelos drop constraint if exists piping_acc_modelos_sistema_check;
alter table public.piping_acc_modelos add constraint piping_acc_modelos_sistema_check check (sistema in ('ASME', 'EN', 'PE'));
alter table public.piping_acc_medidas drop constraint if exists piping_acc_medidas_sistema_check;
alter table public.piping_acc_medidas add constraint piping_acc_medidas_sistema_check check (sistema in ('ASME', 'EN', 'PE'));
on conflict (sistema, dn) do update set od = excluded.od;
on conflict (id) do update set cod = excluded.cod, subtipo = excluded.subtipo, tipo = excluded.tipo, variante = excluded.variante, nombre = excluded.nombre, sistema = excluded.sistema, norma = excluded.norma, conexion = excluded.conexion, mat_grupo = excluded.mat_grupo, esp_tabla = excluded.esp_tabla, notas = excluded.notas, orden = excluded.orden, ratings = excluded.ratings, dn_min = excluded.dn_min, dn_max = excluded.dn_max, fabricante = excluded.fabricante, url = excluded.url, activo = true;
on conflict (modelo, dn, dn2, rating) do update set cotas = excluded.cotas;
commit;
